/// Canonical scheduler stage every generated module is bound to.
pub const PROPERTY_STAGE: &str = "Layer::Infill";

/// Normative core priority for `material`
/// (`slicer_schema::CORE_REGION_SPLIT_PRIORITIES`).
pub const CORE_MATERIAL_PRIORITY: u32 = 100;

/// Normative core priority for `fuzzy_skin`
/// (`slicer_schema::CORE_REGION_SPLIT_PRIORITIES`).
pub const CORE_FUZZY_SKIN_PRIORITY: u32 = 200;

/// Normative minimum priority for a community semantic
/// (`slicer_schema::COMMUNITY_PRIORITY_FLOOR`).
pub const COMMUNITY_PRIORITY_FLOOR: u32 = 1000;

/// Number of generated community semantics available to a case.
pub const COMMUNITY_POOL_SIZE: usize = 4;

/// Bounded pre-sample used by the deterministic population audit.
pub const PRE_SAMPLE_CASES: usize = 128;

/// Bounded tree budget of the deterministic shrink audit.
const SHRINK_AUDIT_MAX_TREES: usize = 32;

/// Bounded simplify budget per audited tree.
const SHRINK_AUDIT_MAX_STEPS: usize = 256;

const MIN_MODULES: u64 = 2;
const MAX_MODULES: u64 = 7;
const MIN_DECLARATIONS: u64 = 2;
const MAX_DECLARATIONS: u64 = 16;
const MIN_TEXT_BYTES: u64 = 8;
const MAX_TEXT_BYTES: u64 = 64;
const MAX_SEMANTIC_POOL: usize = COMMUNITY_POOL_SIZE + 2;

/// Checked H-REGISTRY generation bounds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegistryLimits {
    /// Maximum modules (`2..=7`).
    pub max_modules: u16,
    /// Maximum total declarations (`2..=16`).
    pub max_declarations: usize,
    /// Maximum bytes per variable text component (`8..=64`).
    pub max_text_bytes: usize,
    /// Checked allocation ceiling `max_modules * semantic-pool-size`.
    pub declaration_capacity: usize,
}

/// Reject any registry bound outside the packet's safety ceilings before a
/// strategy allocates.
///
/// The ceiling is a bound, not a target: `max_declarations` may exceed the
/// number of slots a small `max_modules` can hold across the finite semantic
/// pool, in which case the generator uses the reachable subset.
pub fn checked_registry_limits(
    max_modules: u64,
    max_declarations: u64,
    max_text_bytes: u64,
) -> Result<RegistryLimits, String> {
    check_ceiling("max_modules", max_modules, MIN_MODULES, MAX_MODULES)?;
    check_ceiling(
        "max_declarations",
        max_declarations,
        MIN_DECLARATIONS,
        MAX_DECLARATIONS,
    )?;
    check_ceiling(
        "max_text_bytes",
        max_text_bytes,
        MIN_TEXT_BYTES,
        MAX_TEXT_BYTES,
    )?;

    let modules = u16::try_from(max_modules)
        .map_err(|_| format!("max_modules {max_modules} does not fit u16"))?;
    let declarations = usize::try_from(max_declarations)
        .map_err(|_| format!("max_declarations {max_declarations} does not fit usize"))?;
    let text = usize::try_from(max_text_bytes)
        .map_err(|_| format!("max_text_bytes {max_text_bytes} does not fit usize"))?;
    let capacity = usize::from(modules)
        .checked_mul(MAX_SEMANTIC_POOL)
        .ok_or_else(|| {
            format!("max_modules {modules} * semantic pool {MAX_SEMANTIC_POOL} overflowed usize")
        })?;

    Ok(RegistryLimits {
        max_modules: modules,
        max_declarations: declarations,
        max_text_bytes: text,
        declaration_capacity: capacity,
    })
}

fn check_ceiling(name: &str, value: u64, min: u64, max: u64) -> Result<(), String> {
    if !(min..=max).contains(&value) {
        return Err(format!(
            "{name} must be within the H-REGISTRY safety ceiling {min}..={max}, got {value}"
        ));
    }
    Ok(())
}

/// Cross-check this charter's normative priority values against the production
/// catalog (`slicer_schema::CORE_REGION_SPLIT_PRIORITIES` and
/// `slicer_schema::COMMUNITY_PRIORITY_FLOOR`).
pub fn assert_normative_catalog() -> Result<(), String> {
    let expected: &[(&str, u32)] = &[
        ("material", CORE_MATERIAL_PRIORITY),
        ("fuzzy_skin", CORE_FUZZY_SKIN_PRIORITY),
    ];
    if slicer_schema::CORE_REGION_SPLIT_PRIORITIES != expected {
        return Err(format!(
            "slicer_schema::CORE_REGION_SPLIT_PRIORITIES is {:?}, the charter's normative catalog is {expected:?}",
            slicer_schema::CORE_REGION_SPLIT_PRIORITIES
        ));
    }
    if slicer_schema::COMMUNITY_PRIORITY_FLOOR != COMMUNITY_PRIORITY_FLOOR {
        return Err(format!(
            "slicer_schema::COMMUNITY_PRIORITY_FLOOR is {}, the charter's normative floor is {COMMUNITY_PRIORITY_FLOOR}",
            slicer_schema::COMMUNITY_PRIORITY_FLOOR
        ));
    }
    Ok(())
}

/// One declared `[[region_split]]` semantic.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeclarationSpec {
    /// The semantic name.
    pub semantic: String,
    /// Dispatch priority; lower value = higher priority.
    pub priority: u32,
    /// Value-domain the semantic operates on.
    pub value_type: RegionSplitValueType,
}

impl DeclarationSpec {
    /// Construct one declaration specification.
    #[must_use]
    pub fn new(semantic: &str, priority: u32, value_type: RegionSplitValueType) -> Self {
        Self {
            semantic: semantic.to_owned(),
            priority,
            value_type,
        }
    }
}

/// One module's generated declaration list, plus the identity a
/// `LoadedModuleBuilder` needs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModuleSpec {
    /// Reverse-domain module identifier (unique across one case).
    pub module_id: String,
    /// Companion `.wasm` path; also the conflict-warning provenance.
    pub wasm_path: PathBuf,
    /// Declarations, unique per semantic within this manifest.
    pub declarations: Vec<DeclarationSpec>,
}

impl ModuleSpec {
    /// Construct one module specification.
    #[must_use]
    pub fn new(module_id: &str, wasm_path: &str, declarations: Vec<DeclarationSpec>) -> Self {
        Self {
            module_id: module_id.to_owned(),
            wasm_path: PathBuf::from(wasm_path),
            declarations,
        }
    }
}

/// Build the already-loaded aggregation stimulus for one module.
///
/// This intentionally bypasses TOML ingestion: builder-created modules are the
/// positive aggregation domain, not manifest validation coverage (AC-N2 owns
/// raw ingestion rejection).
#[must_use]
pub fn loaded_module(spec: &ModuleSpec) -> LoadedModule {
    LoadedModuleBuilder::new(
        spec.module_id.clone(),
        semver(0, 1, 0),
        PROPERTY_STAGE.to_owned(),
        String::new(),
        spec.wasm_path.clone(),
    )
    .min_host_version(semver(0, 1, 0))
    .min_ir_schema(semver(1, 0, 0))
    .max_ir_schema(semver(5, 0, 0))
    .layer_parallel_safe(true)
    .region_splits(
        spec.declarations
            .iter()
            .map(|declaration| RegionSplitDeclaration {
                semantic: declaration.semantic.clone(),
                priority: declaration.priority,
                value_type: declaration.value_type,
            })
            .collect(),
    )
    .build()
}

/// Whether every repeated semantic agrees on `(priority, value_type)`.
pub fn is_compatible(modules: &[ModuleSpec]) -> bool {
    let mut contracts: BTreeMap<&str, (u32, RegionSplitValueType)> = BTreeMap::new();
    for module in modules {
        for declaration in &module.declarations {
            match contracts.get(declaration.semantic.as_str()) {
                None => {
                    contracts.insert(
                        declaration.semantic.as_str(),
                        (declaration.priority, declaration.value_type),
                    );
                }
                Some(&(priority, value_type)) => {
                    if priority != declaration.priority || value_type != declaration.value_type {
                        return false;
                    }
                }
            }
        }
    }
    true
}

/// One later incompatible declaration the independent model expects to warn
/// about.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExpectedConflict {
    /// The conflicting semantic.
    pub semantic: String,
    /// The later module whose declaration is rejected.
    pub module_id: String,
    /// The later module's `.wasm` path (the warning's `path`).
    pub wasm_path: PathBuf,
    /// Priority the later declaration asked for.
    pub later_priority: u32,
    /// Value type the later declaration asked for.
    pub later_value_type: RegionSplitValueType,
    /// Priority kept from the first-seen declaration.
    pub first_priority: u32,
    /// Value type kept from the first-seen declaration.
    pub first_value_type: RegionSplitValueType,
}

/// Independent relational expectation for one declaration set.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExpectedModel {
    /// Semantic name -> `(priority, value_type, sorted distinct declarers)`.
    pub entries: BTreeMap<String, AggregatedRegionSplitEntry>,
    /// Semantic names in raw `BTreeMap` name order.
    pub raw_keys: Vec<String>,
    /// The separate `(priority, name)` helper sequence.
    pub helper_order: Vec<String>,
    /// Later incompatible declarations, in linear scan order.
    pub conflicts: Vec<ExpectedConflict>,
    /// Tied-priority warning messages, ascending by shared priority.
    pub tie_messages: Vec<String>,
}

/// Derive the independent group/first-seen model for a declaration set.
///
/// `declaring_modules` is a sorted distinct set, so repeating the same loaded
/// module at the aggregation seam cannot change it. A later incompatible
/// declaration keeps the first-seen contract and never joins the declaring set.
pub fn expected_model(modules: &[ModuleSpec]) -> ExpectedModel {
    let mut contracts: BTreeMap<String, (u32, RegionSplitValueType)> = BTreeMap::new();
    let mut declaring: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut conflicts = Vec::new();

    for module in modules {
        for declaration in &module.declarations {
            match contracts.get(&declaration.semantic).copied() {
                None => {
                    contracts.insert(
                        declaration.semantic.clone(),
                        (declaration.priority, declaration.value_type),
                    );
                    declaring
                        .entry(declaration.semantic.clone())
                        .or_default()
                        .insert(module.module_id.clone());
                }
                Some((first_priority, first_value_type))
                    if first_priority == declaration.priority
                        && first_value_type == declaration.value_type =>
                {
                    declaring
                        .entry(declaration.semantic.clone())
                        .or_default()
                        .insert(module.module_id.clone());
                }
                Some((first_priority, first_value_type)) => {
                    conflicts.push(ExpectedConflict {
                        semantic: declaration.semantic.clone(),
                        module_id: module.module_id.clone(),
                        wasm_path: module.wasm_path.clone(),
                        later_priority: declaration.priority,
                        later_value_type: declaration.value_type,
                        first_priority,
                        first_value_type,
                    });
                }
            }
        }
    }

    let mut entries = BTreeMap::new();
    for (semantic, (priority, value_type)) in &contracts {
        entries.insert(
            semantic.clone(),
            AggregatedRegionSplitEntry {
                priority: *priority,
                value_type: *value_type,
                declaring_modules: declaring
                    .get(semantic)
                    .map(|ids| ids.iter().cloned().collect())
                    .unwrap_or_default(),
            },
        );
    }

    let raw_keys: Vec<String> = contracts.keys().cloned().collect();
    let mut priority_name: Vec<(u32, String)> = entries
        .iter()
        .map(|(semantic, entry)| (entry.priority, semantic.clone()))
        .collect();
    priority_name.sort();
    let helper_order = priority_name
        .into_iter()
        .map(|(_priority, semantic)| semantic)
        .collect();
    let tie_messages = tie_warning_messages(&entries);

    ExpectedModel {
        entries,
        raw_keys,
        helper_order,
        conflicts,
        tie_messages,
    }
}

/// Derive the spec's exact tied-priority warning payloads from the aggregate.
///
/// One warning per priority shared by two or more distinct semantics. The
/// payload names the shared priority, every tied semantic with its sorted
/// declaring module ids, and the lexical tiebreaker order; its `path` is the
/// empty `PathBuf` sentinel and its `field` is `Some("region_split")`.
pub fn tie_warning_messages(entries: &BTreeMap<String, AggregatedRegionSplitEntry>) -> Vec<String> {
    let mut by_priority: BTreeMap<u32, Vec<&String>> = BTreeMap::new();
    for (semantic, entry) in entries {
        by_priority
            .entry(entry.priority)
            .or_default()
            .push(semantic);
    }

    let mut messages = Vec::new();
    for (priority, mut semantics) in by_priority {
        if semantics.len() < 2 {
            continue;
        }
        semantics.sort();
        let details: Vec<String> = semantics
            .iter()
            .map(|semantic| {
                let declaring = entries
                    .get(semantic.as_str())
                    .map(|entry| entry.declaring_modules.join(", "))
                    .unwrap_or_default();
                format!("{semantic} (from {declaring})")
            })
            .collect();
        let names = semantics
            .iter()
            .map(|semantic| semantic.as_str())
            .collect::<Vec<_>>()
            .join(", ");
        messages.push(format!(
            "Tied region-split priority {priority}: {}. Lex tiebreaker order: {names}.",
            details.join(", ")
        ));
    }
    messages
}

/// Whether two distinct tied semantics share at least one declaring module.
pub fn has_same_module_tie(entries: &BTreeMap<String, AggregatedRegionSplitEntry>) -> bool {
    priority_groups(entries).values().any(|group| {
        group.iter().enumerate().any(|(index, left)| {
            group[index + 1..]
                .iter()
                .any(|right| left.iter().any(|module| right.contains(module)))
        })
    })
}

/// Whether two distinct tied semantics have non-identical declaring sets.
pub fn has_cross_module_tie(entries: &BTreeMap<String, AggregatedRegionSplitEntry>) -> bool {
    priority_groups(entries).values().any(|group| {
        group.iter().enumerate().any(|(index, left)| {
            group[index + 1..].iter().any(|right| {
                left.iter().any(|module| !right.contains(module))
                    || right.iter().any(|module| !left.contains(module))
            })
        })
    })
}

fn priority_groups<'a>(
    entries: &'a BTreeMap<String, AggregatedRegionSplitEntry>,
) -> BTreeMap<u32, Vec<&'a Vec<String>>> {
    let mut by_priority: BTreeMap<u32, Vec<&Vec<String>>> = BTreeMap::new();
    for entry in entries.values() {
        by_priority
            .entry(entry.priority)
            .or_default()
            .push(&entry.declaring_modules);
    }
    by_priority
}

/// A distinctive preexisting diagnostic. Aggregation must append to the caller's
/// `Vec`, never clear or reorder it.
fn sentinel_diagnostic() -> LoadDiagnostic {
    LoadDiagnostic {
        level: DiagnosticLevel::Error,
        path: PathBuf::from("fixtures/preexisting-registry-sentinel.wasm"),
        field: Some("preexisting_registry_sentinel".to_owned()),
        message: "preexisting scheduler diagnostic that region-split aggregation must never clear"
            .to_owned(),
    }
}

/// Compare one observed aggregate/diagnostic triple to the independent model.
///
/// The raw keys must be semantic-name ordered, `helper_order` must be the direct
/// `canonical_variant_chain_order` result, and diagnostics must be exactly the
/// unchanged sentinel followed by the model's conflict warnings (linear scan
/// order) and tied-priority warnings (ascending priority).
pub fn check_registry_observation(
    actual_map: &BTreeMap<String, AggregatedRegionSplitEntry>,
    helper_order: &[String],
    diagnostics: &[LoadDiagnostic],
    sentinel: &LoadDiagnostic,
    model: &ExpectedModel,
    context: &str,
) -> Result<(), String> {
    compare_entries(actual_map, &model.entries, context)?;

    let actual_names: Vec<String> = actual_map.keys().cloned().collect();
    if actual_names != model.raw_keys {
        return Err(format!(
            "{context}: raw map keys {actual_names:?} are not the semantic-name-ordered keys {:?}",
            model.raw_keys
        ));
    }

    if helper_order != model.helper_order.as_slice() {
        return Err(format!(
            "{context}: canonical_variant_chain_order returned {helper_order:?}, the independent (priority, name) model expects {:?}",
            model.helper_order
        ));
    }

    let expected_diagnostics = 1 + model.conflicts.len() + model.tie_messages.len();
    if diagnostics.len() != expected_diagnostics {
        return Err(format!(
            "{context}: expected {expected_diagnostics} diagnostics (sentinel + {} conflict warning(s) + {} tied-priority warning(s)), got {}: {diagnostics:?}",
            model.conflicts.len(),
            model.tie_messages.len(),
            diagnostics.len()
        ));
    }
    match diagnostics.first() {
        Some(first) if first == sentinel => {}
        _ => {
            return Err(format!(
                "{context}: the preexisting sentinel diagnostic was cleared or reordered: {diagnostics:?}"
            ));
        }
    }

    for (index, conflict) in model.conflicts.iter().enumerate() {
        let diagnostic = &diagnostics[1 + index];
        if diagnostic.level != DiagnosticLevel::Warning {
            return Err(format!(
                "{context}: conflict for semantic {:?} must be a Warning, got {:?}",
                conflict.semantic, diagnostic.level
            ));
        }
        if diagnostic.path != conflict.wasm_path {
            return Err(format!(
                "{context}: conflict warning for module {:?} must carry path {:?}, got {:?}",
                conflict.module_id, conflict.wasm_path, diagnostic.path
            ));
        }
        if diagnostic.field.as_deref() != Some("region_split") {
            return Err(format!(
                "{context}: conflict warning for module {:?} must carry field Some(\"region_split\"), got {:?}",
                conflict.module_id, diagnostic.field
            ));
        }
        let later = format!(
            "priority={}/value_type={:?}",
            conflict.later_priority, conflict.later_value_type
        );
        let earlier = format!(
            "priority={}/value_type={:?}",
            conflict.first_priority, conflict.first_value_type
        );
        let required = [
            format!("semantic \"{}\"", conflict.semantic),
            format!("module \"{}\"", conflict.module_id),
            later,
            earlier,
        ];
        for fragment in &required {
            if !diagnostic.message.contains(fragment.as_str()) {
                return Err(format!(
                    "{context}: conflict warning for module {:?} does not name {fragment:?}: {}",
                    conflict.module_id, diagnostic.message
                ));
            }
        }
    }

    for (offset, message) in model.tie_messages.iter().enumerate() {
        let diagnostic = &diagnostics[1 + model.conflicts.len() + offset];
        let expected = LoadDiagnostic {
            level: DiagnosticLevel::Warning,
            path: PathBuf::new(),
            field: Some("region_split".to_owned()),
            message: message.clone(),
        };
        if diagnostic != &expected {
            return Err(format!(
                "{context}: tied-priority warning payload is {diagnostic:?}, expected {expected:?}"
            ));
        }
    }

    Ok(())
}

fn compare_entries(
    actual: &BTreeMap<String, AggregatedRegionSplitEntry>,
    expected: &BTreeMap<String, AggregatedRegionSplitEntry>,
    context: &str,
) -> Result<(), String> {
    for (semantic, expected_entry) in expected {
        match actual.get(semantic) {
            None => {
                return Err(format!(
                    "{context}: aggregate omits declared semantic {semantic:?}"
                ));
            }
            Some(actual_entry) if actual_entry != expected_entry => {
                return Err(format!(
                    "{context}: aggregate entry for {semantic:?} is {actual_entry:?}, the independent group model expects {expected_entry:?}"
                ));
            }
            Some(_) => {}
        }
    }
    for semantic in actual.keys() {
        if !expected.contains_key(semantic) {
            return Err(format!(
                "{context}: aggregate reports undeclared semantic {semantic:?}; aggregation must not seed semantics"
            ));
        }
    }
    Ok(())
}

/// One sampled H-REGISTRY case.
#[derive(Debug)]
struct Sample {
    /// Structural declaration set.
    case: RegistryCase,
    /// Permutation of module indices.
    module_order: Vec<usize>,
    /// Per-module permutation of declaration indices, in original module order.
    declaration_orders: Vec<Vec<usize>>,
    /// Module index repeated directly at the aggregation seam.
    repeat_index: usize,
    /// Whether to also drive the real `build_execution_plan` seam.
    plan_mode: bool,
}

/// The shape a case was constructed to guarantee.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RequestedShape {
    Compatible,
    Conflicting,
    TiedSameModule,
    TiedCrossModule,
}

impl RequestedShape {
    /// Human-readable tag used in audit failure messages.
    fn label(self) -> &'static str {
        match self {
            Self::Compatible => "Compatible",
            Self::Conflicting => "Conflicting",
            Self::TiedSameModule => "TiedSameModule",
            Self::TiedCrossModule => "TiedCrossModule",
        }
    }
}

/// How a deliberately incompatible later declaration differs from the
/// first-seen contract.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConflictKind {
    /// Raise the priority (community semantics only).
    Priority,
    /// Switch the value type (legal for every semantic, including core).
    ValueType,
}

/// Non-shrinkable descriptor of the fault one case must exhibit.
///
/// Every field that decides whether — or which — fault exists lives here and is
/// drawn through a `no_shrink` `proptest::sample::select`, so `simplify()` can
/// never turn a conflicting or tied case into a compatible one, move the shared
/// or tied semantics to another pool entry, or change the conflicting contract.
/// Only the module/declaration counts, the text stem and the
/// order/repetition/plan-seam choices shrink.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CasePlan {
    /// The guaranteed declaration shape.
    shape: RequestedShape,
    /// Whether the generated pool includes `material`.
    include_material: bool,
    /// Whether the generated pool includes `fuzzy_skin`.
    include_fuzzy: bool,
    /// Shared semantic (compatible/conflicting) or first tied semantic (tie
    /// shapes) as an index into the generated pool.
    slot: usize,
    /// Offset of the second tied semantic inside the community prefix.
    tie_offset: usize,
    /// Conflict flavour for `RequestedShape::Conflicting`.
    conflict: ConflictKind,
}

/// Structural declaration set plus the shape it is expected to exhibit.
#[derive(Debug, Clone)]
struct RegistryCase {
    modules: Vec<ModuleSpec>,
    requested: RequestedShape,
}

/// Non-shrinkable pool compositions.
const POOL_COMPOSITIONS: [(bool, bool); 4] =
    [(false, false), (true, false), (false, true), (true, true)];

/// Enumerate every non-shrinkable plan for one shape.
///
/// Core slots only enumerate a value-type conflict: `material`/`fuzzy_skin`
/// must keep their normative priority, so the conflicting declaration switches
/// the value type instead. Tie slots index the community prefix because core
/// priorities can never tie with the floor.
fn case_plans(shape: RequestedShape) -> Vec<CasePlan> {
    let mut plans = Vec::new();
    for (include_material, include_fuzzy) in POOL_COMPOSITIONS {
        match shape {
            RequestedShape::Compatible | RequestedShape::Conflicting => {
                let mut pool_len = COMMUNITY_POOL_SIZE;
                if include_material {
                    pool_len += 1;
                }
                if include_fuzzy {
                    pool_len += 1;
                }
                for slot in 0..pool_len {
                    let community_slot = slot < COMMUNITY_POOL_SIZE;
                    let kinds: &[ConflictKind] =
                        if shape == RequestedShape::Conflicting && community_slot {
                            &[ConflictKind::Priority, ConflictKind::ValueType]
                        } else {
                            &[ConflictKind::ValueType]
                        };
                    for &conflict in kinds {
                        plans.push(CasePlan {
                            shape,
                            include_material,
                            include_fuzzy,
                            slot,
                            tie_offset: 0,
                            conflict,
                        });
                    }
                }
            }
            RequestedShape::TiedSameModule | RequestedShape::TiedCrossModule => {
                for slot in 0..COMMUNITY_POOL_SIZE {
                    for tie_offset in 0..(COMMUNITY_POOL_SIZE - 1) {
                        plans.push(CasePlan {
                            shape,
                            include_material,
                            include_fuzzy,
                            slot,
                            tie_offset,
                            conflict: ConflictKind::ValueType,
                        });
                    }
                }
            }
        }
    }
    plans
}

/// Registry-bounded case-construction strategy.
///
/// The requested shape and its fault descriptor are drawn from two chained
/// `no_shrink` selections, so `simplify()` can only shrink the module and
/// declaration counts and the text stem. A shrinkable `any::<u8>()` shape or
/// `conflict_bits`/`pool_bits` word would let shrinking erase the conflicting
/// or tied witness the charter says must survive.
///
/// [`sample_strategy`] adds the shrink-safe module/declaration permutations,
/// seam-repetition candidate and plan-assembly flag downstream; those are
/// separate [`Sample`] fields computed from `case`, so simplifying them can
/// never change the case itself.
fn case_strategy(limits: RegistryLimits) -> Result<BoxedStrategy<RegistryCase>, String> {
    let max_modules = usize::from(limits.max_modules);
    let module_slots = u16::try_from(max_modules - 1)
        .map_err(|_| format!("max_modules {max_modules} - 1 does not fit u16"))?;
    let declaration_ceiling = limits
        .max_declarations
        .min(limits.declaration_capacity)
        .max(usize::try_from(MIN_DECLARATIONS).expect("2 fits usize"));
    let declaration_slots = u8::try_from(declaration_ceiling - 1)
        .map_err(|_| format!("declaration ceiling {declaration_ceiling} - 1 does not fit u8"))?;
    let stem = id_text(IdTextKind::OtherText, limits.max_text_bytes).map_err(|error| {
        format!(
            "H-REGISTRY variable name domain rejected {} bytes: {error}",
            limits.max_text_bytes
        )
    })?;

    let shapes = vec![
        RequestedShape::Compatible,
        RequestedShape::Conflicting,
        RequestedShape::TiedSameModule,
        RequestedShape::TiedCrossModule,
    ];
    Ok(proptest::sample::select(shapes)
        .no_shrink()
        .prop_flat_map(move |shape| {
            let stem = stem.clone();
            proptest::sample::select(case_plans(shape))
                .no_shrink()
                .prop_flat_map(move |plan| {
                    let stem = stem.clone();
                    (0u16..module_slots, 0u8..declaration_slots, stem).prop_map(
                        move |(module_slot, declaration_slot, stem)| {
                            build_case(limits, plan, module_slot, declaration_slot, &stem)
                        },
                    )
                })
        })
        .boxed())
}

/// Registry-bounded strategy for the compatible/conflicting/tied declaration
/// shapes plus a module order permutation, per-module declaration permutations,
/// a seam-duplication candidate and an optional plan-assembly mode.
fn sample_strategy(limits: &RegistryLimits) -> Result<BoxedStrategy<Sample>, String> {
    Ok(case_strategy(*limits)?
        .prop_flat_map(|case| {
            let module_order = permutations(case.modules.len());
            let declaration_lengths: Vec<usize> = case
                .modules
                .iter()
                .map(|module| module.declarations.len())
                .collect();
            let declaration_orders = declaration_order_strategy(&declaration_lengths);
            let repeat_range = 0usize..case.modules.len();
            (
                module_order,
                declaration_orders,
                repeat_range,
                any::<bool>(),
            )
                .prop_map(
                    move |(module_order, declaration_orders, repeat_index, plan_mode)| Sample {
                        case: case.clone(),
                        module_order,
                        declaration_orders,
                        repeat_index,
                        plan_mode,
                    },
                )
        })
        .boxed())
}

/// Compose one permutation strategy per module's declaration count.
fn declaration_order_strategy(lengths: &[usize]) -> BoxedStrategy<Vec<Vec<usize>>> {
    match lengths.split_first() {
        None => Just(Vec::new()).boxed(),
        Some((&first, rest)) => {
            let head = permutations(first);
            let tail = declaration_order_strategy(rest);
            (head, tail)
                .prop_map(|(head, mut tail)| {
                    tail.insert(0, head);
                    tail
                })
                .boxed()
        }
    }
}

/// Build one guaranteed-shape case from a non-shrinkable plan plus the
/// shrinkable module count, declaration budget and text stem.
fn build_case(
    limits: RegistryLimits,
    plan: CasePlan,
    module_slot: u16,
    declaration_slot: u8,
    stem: &str,
) -> RegistryCase {
    let max_modules = usize::from(limits.max_modules);
    let module_count = 2 + usize::from(module_slot) % (max_modules - 1);
    let declaration_ceiling = limits
        .max_declarations
        .min(limits.declaration_capacity)
        .max(usize::try_from(MIN_DECLARATIONS).expect("2 fits usize"));
    let declaration_budget = 2 + usize::from(declaration_slot) % (declaration_ceiling - 1);

    let pool = semantic_pool(stem, plan);
    debug_assert!(plan.slot < pool.len());

    let mut modules: Vec<ModuleSpec> = (0..module_count)
        .map(|index| ModuleSpec {
            module_id: format!("com.pbt.module-{index}-{stem}"),
            wasm_path: PathBuf::from(format!("fixtures/com.pbt.module-{index}-{stem}.wasm")),
            declarations: Vec::new(),
        })
        .collect();

    match plan.shape {
        RequestedShape::Compatible | RequestedShape::Conflicting => {
            // Declaring the shared semantic from every module (up to the
            // declaration budget) keeps the compatible/conflicting fault
            // invariant under module- and declaration-count shrinking.
            let shared_size = module_count.min(declaration_budget);
            debug_assert!(shared_size >= 2);
            for module in modules.iter_mut().take(shared_size) {
                module.declarations.push(pool[plan.slot].clone());
            }
            if plan.shape == RequestedShape::Conflicting {
                let last = shared_size - 1;
                modules[last].declarations.clear();
                modules[last]
                    .declarations
                    .push(conflict_variant(&pool[plan.slot], plan.conflict));
            }
            add_extra_declarations(
                &mut modules,
                &pool,
                plan.slot,
                declaration_budget - shared_size,
                plan,
            );
        }
        RequestedShape::TiedSameModule => {
            let (first, second) = tie_pair(plan);
            modules[0].declarations.push(pool[first].clone());
            modules[0].declarations.push(pool[second].clone());
            if declaration_budget >= 3 && module_count >= 2 {
                modules[1].declarations.push(pool[first].clone());
            }
        }
        RequestedShape::TiedCrossModule => {
            let (first, second) = tie_pair(plan);
            modules[0].declarations.push(pool[first].clone());
            modules[1].declarations.push(pool[second].clone());
            if declaration_budget >= 3 && module_count >= 3 {
                modules[2].declarations.push(pool[first].clone());
            }
            if declaration_budget >= 4 && module_count >= 4 {
                modules[3].declarations.push(pool[second].clone());
            }
        }
    }

    RegistryCase {
        modules,
        requested: plan.shape,
    }
}

/// The finite semantic pool: four generated community names plus the two core
/// semantics when requested. Core entries keep their exact normative priority
/// and canonical value type; community entries sit at or above the floor.
///
/// Tie shapes put every community entry at the floor so the two selected
/// semantics share one priority. Compatible/conflicting shapes give each
/// community entry a distinct priority so they cannot accidentally tie.
fn semantic_pool(stem: &str, plan: CasePlan) -> Vec<DeclarationSpec> {
    let tie_communities = matches!(
        plan.shape,
        RequestedShape::TiedSameModule | RequestedShape::TiedCrossModule
    );
    let mut pool = Vec::with_capacity(MAX_SEMANTIC_POOL);
    for index in 0..COMMUNITY_POOL_SIZE {
        let priority = if tie_communities {
            COMMUNITY_PRIORITY_FLOOR
        } else {
            COMMUNITY_PRIORITY_FLOOR + u32::try_from(index).expect("community pool index fits u32")
        };
        pool.push(DeclarationSpec {
            semantic: format!("com.pbt.semantic-{index}-{stem}"),
            priority,
            value_type: value_type_for(index),
        });
    }
    if plan.include_material {
        pool.push(DeclarationSpec::new(
            "material",
            CORE_MATERIAL_PRIORITY,
            RegionSplitValueType::ToolIndex,
        ));
    }
    if plan.include_fuzzy {
        pool.push(DeclarationSpec::new(
            "fuzzy_skin",
            CORE_FUZZY_SKIN_PRIORITY,
            RegionSplitValueType::Flag,
        ));
    }
    pool
}

/// Add one distinct declared semantic per remaining budget slot, starting after
/// the shared entry so no extra can repeat the shared or conflicting semantic.
fn add_extra_declarations(
    modules: &mut [ModuleSpec],
    pool: &[DeclarationSpec],
    shared: usize,
    budget: usize,
    plan: CasePlan,
) {
    let extra_count = budget.min(pool.len() - 1);
    for offset in 0..extra_count {
        let pool_index = (shared + 1 + offset) % pool.len();
        let module_index = (plan.slot + offset) % modules.len();
        modules[module_index]
            .declarations
            .push(pool[pool_index].clone());
    }
}

/// The two distinct community semantics a tie shape places at the floor.
fn tie_pair(plan: CasePlan) -> (usize, usize) {
    let first = plan.slot % COMMUNITY_POOL_SIZE;
    let second = (first + 1 + plan.tie_offset) % COMMUNITY_POOL_SIZE;
    (first, second)
}

/// The later declaration that must lose to the first-seen contract.
///
/// A priority conflict is only enumerated for community slots, which sit at or
/// above `COMMUNITY_PRIORITY_FLOOR`; core semantics keep their normative
/// priority and can only conflict by value type.
fn conflict_variant(original: &DeclarationSpec, kind: ConflictKind) -> DeclarationSpec {
    match kind {
        ConflictKind::Priority => {
            debug_assert!(original.priority >= COMMUNITY_PRIORITY_FLOOR);
            DeclarationSpec {
                semantic: original.semantic.clone(),
                priority: original.priority + 1,
                value_type: original.value_type,
            }
        }
        ConflictKind::ValueType => DeclarationSpec {
            semantic: original.semantic.clone(),
            priority: original.priority,
            value_type: next_value_type(original.value_type),
        },
    }
}

fn value_type_for(index: usize) -> RegionSplitValueType {
    const VALUE_TYPES: [RegionSplitValueType; 3] = [
        RegionSplitValueType::Flag,
        RegionSplitValueType::ToolIndex,
        RegionSplitValueType::CustomString,
    ];
    VALUE_TYPES[index % VALUE_TYPES.len()]
}

fn next_value_type(value_type: RegionSplitValueType) -> RegionSplitValueType {
    match value_type {
        RegionSplitValueType::Flag => RegionSplitValueType::ToolIndex,
        RegionSplitValueType::ToolIndex => RegionSplitValueType::CustomString,
        RegionSplitValueType::CustomString => RegionSplitValueType::Flag,
    }
}

fn semver(major: u32, minor: u32, patch: u32) -> SemVer {
    SemVer {
        major,
        minor,
        patch,
    }
}

fn loaded_modules(specs: &[ModuleSpec]) -> Vec<LoadedModule> {
    specs.iter().map(loaded_module).collect()
}

/// Reorder modules and, within each module, declarations.
fn permuted_modules(
    modules: &[ModuleSpec],
    module_order: &[usize],
    declaration_orders: &[Vec<usize>],
) -> Result<Vec<ModuleSpec>, String> {
    if !is_permutation(module_order, modules.len()) {
        return Err(format!(
            "module order {module_order:?} is not a permutation of {} modules",
            modules.len()
        ));
    }
    if declaration_orders.len() != modules.len() {
        return Err(format!(
            "expected {} per-module declaration orders, got {}",
            modules.len(),
            declaration_orders.len()
        ));
    }

    let mut permuted = Vec::with_capacity(modules.len());
    for &module_index in module_order {
        let module = &modules[module_index];
        let order = &declaration_orders[module_index];
        if !is_permutation(order, module.declarations.len()) {
            return Err(format!(
                "declaration order {order:?} is not a permutation of {} declarations for module {}",
                module.declarations.len(),
                module.module_id
            ));
        }
        permuted.push(ModuleSpec {
            module_id: module.module_id.clone(),
            wasm_path: module.wasm_path.clone(),
            declarations: order
                .iter()
                .map(|&declaration_index| module.declarations[declaration_index].clone())
                .collect(),
        });
    }
    Ok(permuted)
}

fn aggregate_with_sentinel(
    modules: &[LoadedModule],
    sentinel: &LoadDiagnostic,
) -> (
    BTreeMap<String, AggregatedRegionSplitEntry>,
    Vec<LoadDiagnostic>,
    Vec<String>,
) {
    let mut diagnostics = vec![sentinel.clone()];
    let aggregate = aggregate_region_splits(modules, &mut diagnostics);
    let helper = canonical_variant_chain_order(&aggregate);
    (aggregate, diagnostics, helper)
}

/// Build a real plan from unique bindings and return its aggregate plus the
/// diagnostics `build_execution_plan` appended.
fn build_plan(
    case: &RegistryCase,
    resolved: &ResolvedConfig,
    sentinel: &LoadDiagnostic,
) -> Result<
    (
        BTreeMap<String, AggregatedRegionSplitEntry>,
        Vec<LoadDiagnostic>,
    ),
    String,
> {
    let bindings: Vec<ExecutionModuleBinding> = case
        .modules
        .iter()
        .map(|spec| {
            let module = loaded_module(spec);
            let config_view = bind_module_config_view(&module, resolved);
            ExecutionModuleBinding {
                module,
                config_view,
            }
        })
        .collect();
    let module_ids: Vec<String> = case
        .modules
        .iter()
        .map(|spec| spec.module_id.clone())
        .collect();
    let request = ExecutionPlanRequest {
        sorted_stages: vec![SortedStageModules {
            stage_id: PROPERTY_STAGE.to_owned(),
            module_ids,
        }],
        module_bindings: bindings,
        global_layers: Arc::new(Vec::<GlobalLayer>::new()),
        region_plans: Arc::new(HashMap::<RegionKey, RegionPlan>::new()),
    };

    let mut diagnostics = vec![sentinel.clone()];
    let plan = build_execution_plan(&request, &mut diagnostics).map_err(|error| {
        format!("build_execution_plan rejected the generated unique bindings: {error:?}")
    })?;
    Ok((plan.aggregated_region_split, diagnostics))
}

/// Check one sampled case against the independent model.
fn check_sample(sample: &Sample) -> Result<(), String> {
    let case = &sample.case;
    let compatible = is_compatible(&case.modules);
    let model = expected_model(&case.modules);
    if model.entries.is_empty() {
        return Err(String::from(
            "H-REGISTRY generated an empty aggregate; every case must declare at least two semantics",
        ));
    }

    match case.requested {
        RequestedShape::Compatible => {
            if !compatible {
                return Err(String::from(
                    "compatible-mode case contains an incompatible repeated declaration",
                ));
            }
        }
        RequestedShape::Conflicting => {
            if compatible {
                return Err(String::from(
                    "conflicting-mode case contains no incompatible repeated declaration",
                ));
            }
        }
        RequestedShape::TiedSameModule => {
            if !compatible {
                return Err(String::from(
                    "same-module-tie case contains an incompatible repeated declaration",
                ));
            }
            if !has_same_module_tie(&model.entries) {
                return Err(String::from(
                    "same-module-tie case produced no priority shared by two semantics declared by one module",
                ));
            }
        }
        RequestedShape::TiedCrossModule => {
            if !compatible {
                return Err(String::from(
                    "cross-module-tie case contains an incompatible repeated declaration",
                ));
            }
            if !has_cross_module_tie(&model.entries) {
                return Err(String::from(
                    "cross-module-tie case produced no tie between semantics from different modules",
                ));
            }
        }
    }

    let sentinel = sentinel_diagnostic();

    let modules = loaded_modules(&case.modules);
    let (aggregate, diagnostics, helper) = aggregate_with_sentinel(&modules, &sentinel);
    check_registry_observation(
        &aggregate,
        &helper,
        &diagnostics,
        &sentinel,
        &model,
        "generation-order aggregation",
    )?;

    let permuted = permuted_modules(
        &case.modules,
        &sample.module_order,
        &sample.declaration_orders,
    )?;
    let permuted_model = expected_model(&permuted);
    let (permuted_aggregate, permuted_diagnostics, permuted_helper) =
        aggregate_with_sentinel(&loaded_modules(&permuted), &sentinel);
    check_registry_observation(
        &permuted_aggregate,
        &permuted_helper,
        &permuted_diagnostics,
        &sentinel,
        &permuted_model,
        "module-and-declaration-permuted aggregation",
    )?;
    if compatible {
        if permuted_aggregate != aggregate {
            return Err(format!(
                "permuting modules/declarations changed the compatible aggregate: {:?} vs {:?}",
                aggregate, permuted_aggregate
            ));
        }
        if permuted_helper != helper {
            return Err(format!(
                "permuting modules/declarations changed the (priority, name) helper sequence: {:?} vs {:?}",
                helper, permuted_helper
            ));
        }
        if permuted_diagnostics != diagnostics {
            return Err(format!(
                "permuting modules/declarations changed the tied-priority warning payload: {:?} vs {:?}",
                diagnostics, permuted_diagnostics
            ));
        }
    }

    if sample.repeat_index >= case.modules.len() {
        return Err(format!(
            "repeat index {} is outside {} modules",
            sample.repeat_index,
            case.modules.len()
        ));
    }
    let mut repeated = case.modules.clone();
    repeated.push(case.modules[sample.repeat_index].clone());
    let repeated_model = expected_model(&repeated);
    let (repeated_aggregate, repeated_diagnostics, repeated_helper) =
        aggregate_with_sentinel(&loaded_modules(&repeated), &sentinel);
    check_registry_observation(
        &repeated_aggregate,
        &repeated_helper,
        &repeated_diagnostics,
        &sentinel,
        &repeated_model,
        "seam-repeated-module aggregation",
    )?;
    for (semantic, entry) in &repeated_aggregate {
        let unique: BTreeSet<&String> = entry.declaring_modules.iter().collect();
        if unique.len() != entry.declaring_modules.len() {
            return Err(format!(
                "repeating module {:?} at the aggregation seam duplicated a declarer for {semantic:?}: {:?}",
                case.modules[sample.repeat_index].module_id,
                entry.declaring_modules
            ));
        }
    }
    if compatible {
        if repeated_aggregate != aggregate {
            return Err(format!(
                "repeating a compatible module at the aggregation seam changed the aggregate: {:?} vs {:?}",
                aggregate, repeated_aggregate
            ));
        }
        if repeated_diagnostics != diagnostics {
            return Err(format!(
                "repeating a compatible module at the aggregation seam changed diagnostics: {:?} vs {:?}",
                diagnostics, repeated_diagnostics
            ));
        }
        if repeated_helper != helper {
            return Err(String::from(
                "repeating a compatible module at the aggregation seam changed the helper sequence",
            ));
        }
    }

    if sample.plan_mode {
        let resolved = ResolvedConfig::default();
        let (plan_aggregate, plan_diagnostics) = build_plan(case, &resolved, &sentinel)?;
        if plan_aggregate.is_empty() {
            return Err(String::from(
                "plan-assembled aggregate is empty for a non-empty binding set: build_execution_plan stopped calling aggregate_region_splits",
            ));
        }
        check_registry_observation(
            &plan_aggregate,
            &canonical_variant_chain_order(&plan_aggregate),
            &plan_diagnostics,
            &sentinel,
            &model,
            "plan-assembled aggregation",
        )?;
    }

    Ok(())
}

/// Deterministic population guard.
///
/// Fails loudly when a bounded pre-sample reaches none of the modes this
/// property claims to explore: no `prop_assume`, no rejection budget.
fn assert_substantive_population(strategy: &BoxedStrategy<Sample>) -> Result<(), String> {
    if PRE_SAMPLE_CASES == 0 {
        return Err(String::from("pre-sample size must be positive"));
    }
    let cases = u32::try_from(PRE_SAMPLE_CASES)
        .map_err(|_| format!("pre-sample size {PRE_SAMPLE_CASES} does not fit u32"))?;
    let mut runner = TestRunner::new(Config {
        cases,
        max_local_rejects: 0,
        rng_algorithm: RngAlgorithm::ChaCha,
        rng_seed: RngSeed::Fixed(0x5eed_c0de),
        failure_persistence: None,
        ..Config::default()
    });

    let sentinel = sentinel_diagnostic();
    let mut compatible = 0usize;
    let mut conflicting = 0usize;
    let mut tied = 0usize;
    let mut same_module_tie = 0usize;
    let mut cross_module_tie = 0usize;
    let mut nonempty_aggregate = 0usize;
    let mut tied_warning = 0usize;

    for _ in 0..PRE_SAMPLE_CASES {
        let sample = strategy
            .new_tree(&mut runner)
            .map_err(|error| format!("H-REGISTRY pre-sample strategy rejected a case: {error}"))?
            .current();
        let case = &sample.case;
        match case.requested {
            RequestedShape::Compatible => compatible += 1,
            RequestedShape::Conflicting => conflicting += 1,
            RequestedShape::TiedSameModule | RequestedShape::TiedCrossModule => tied += 1,
        }

        let model = expected_model(&case.modules);
        if has_same_module_tie(&model.entries) {
            same_module_tie += 1;
        }
        if has_cross_module_tie(&model.entries) {
            cross_module_tie += 1;
        }

        let (aggregate, diagnostics, _) =
            aggregate_with_sentinel(&loaded_modules(&case.modules), &sentinel);
        if !aggregate.is_empty() {
            nonempty_aggregate += 1;
        }
        if diagnostics.iter().any(|diagnostic| {
            diagnostic.level == DiagnosticLevel::Warning
                && diagnostic.path.as_os_str().is_empty()
                && diagnostic.field.as_deref() == Some("region_split")
                && diagnostic
                    .message
                    .starts_with("Tied region-split priority ")
        }) {
            tied_warning += 1;
        }
    }

    if compatible == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a compatible declaration shape"
        ));
    }
    if conflicting == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a conflicting declaration shape"
        ));
    }
    if tied == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a tied-priority shape"
        ));
    }
    if same_module_tie == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a same-module tie"
        ));
    }
    if cross_module_tie == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a cross-module tie"
        ));
    }
    if nonempty_aggregate == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a non-empty aggregate"
        ));
    }
    if tied_warning == 0 {
        return Err(format!(
            "pre-sample of {PRE_SAMPLE_CASES} cases never produced a tied-priority warning"
        ));
    }

    Ok(())
}

/// The fault a shrink step must preserve, sampled once per audited tree.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ShapeWitness {
    /// Requested shape tag.
    shape: RequestedShape,
    /// Conflicting shapes: the contract kept from the first declaration.
    first_seen: Option<(u32, RegionSplitValueType)>,
    /// Tied shapes: the shared priority whose single warning must survive.
    tie_priority: Option<u32>,
}

/// Index of a shape in the fixed-size audit roster.
fn shape_index(shape: RequestedShape) -> usize {
    match shape {
        RequestedShape::Compatible => 0,
        RequestedShape::Conflicting => 1,
        RequestedShape::TiedSameModule => 2,
        RequestedShape::TiedCrossModule => 3,
    }
}

/// The lowest priority shared by two or more aggregated semantics.
fn tied_priority(entries: &BTreeMap<String, AggregatedRegionSplitEntry>) -> Option<u32> {
    let mut counts: BTreeMap<u32, usize> = BTreeMap::new();
    for entry in entries.values() {
        *counts.entry(entry.priority).or_default() += 1;
    }
    counts
        .into_iter()
        .find_map(|(priority, count)| (count >= 2).then_some(priority))
}

/// Independent fault fingerprint of one generated case.
fn shape_witness(case: &RegistryCase) -> ShapeWitness {
    let model = expected_model(&case.modules);
    let (first_seen, tie_priority) = match case.requested {
        RequestedShape::Compatible => (None, None),
        RequestedShape::Conflicting => {
            let conflict = model.conflicts.first().unwrap_or_else(|| {
                panic!(
                    "H-REGISTRY shrink audit: conflicting case has no incompatible repeated declaration (modules: {:?})",
                    case.modules
                )
            });
            let entry = model.entries.get(&conflict.semantic).unwrap_or_else(|| {
                panic!(
                    "H-REGISTRY shrink audit: conflicting case lost the first-seen entry for {:?}",
                    conflict.semantic
                )
            });
            (Some((entry.priority, entry.value_type)), None)
        }
        RequestedShape::TiedSameModule | RequestedShape::TiedCrossModule => {
            (None, tied_priority(&model.entries))
        }
    };
    ShapeWitness {
        shape: case.requested,
        first_seen,
        tie_priority,
    }
}

/// Re-derive one case's fault from the independent model and the real
/// aggregator, asserting the shape still carries exactly its witness.
fn assert_case_fault_intact(case: &RegistryCase) {
    let model = expected_model(&case.modules);
    let sentinel = sentinel_diagnostic();
    let (aggregate, diagnostics, _) =
        aggregate_with_sentinel(&loaded_modules(&case.modules), &sentinel);

    let conflict_warnings = diagnostics
        .iter()
        .filter(|diagnostic| {
            diagnostic.level == DiagnosticLevel::Warning
                && !diagnostic.path.as_os_str().is_empty()
                && diagnostic.field.as_deref() == Some("region_split")
        })
        .count();
    let tie_warnings = diagnostics
        .iter()
        .filter(|diagnostic| {
            diagnostic.level == DiagnosticLevel::Warning
                && diagnostic.path.as_os_str().is_empty()
                && diagnostic.field.as_deref() == Some("region_split")
                && diagnostic
                    .message
                    .starts_with("Tied region-split priority ")
        })
        .count();

    match case.requested {
        RequestedShape::Compatible => {
            assert!(
                is_compatible(&case.modules),
                "H-REGISTRY shrink audit: a compatible case gained an incompatible repeated declaration"
            );
            assert!(
                model.conflicts.is_empty(),
                "H-REGISTRY shrink audit: a compatible case's independent model expects {} conflict(s): {:?}",
                model.conflicts.len(),
                model.conflicts
            );
            assert_eq!(
                conflict_warnings, 0,
                "H-REGISTRY shrink audit: a compatible case produced an incompatible warning: {diagnostics:?}"
            );
            assert_eq!(
                tie_warnings, 0,
                "H-REGISTRY shrink audit: a compatible case produced a tied-priority warning: {diagnostics:?}"
            );
        }
        RequestedShape::Conflicting => {
            assert!(
                !is_compatible(&case.modules),
                "H-REGISTRY shrink audit: a conflicting case lost its incompatible repeated declaration"
            );
            assert_eq!(
                model.conflicts.len(),
                1,
                "H-REGISTRY shrink audit: a conflicting case must keep exactly one incompatible declaration, got {}: {:?}",
                model.conflicts.len(),
                model.conflicts
            );
            let conflict = &model.conflicts[0];
            let kept = model.entries.get(&conflict.semantic).unwrap_or_else(|| {
                panic!(
                    "H-REGISTRY shrink audit: conflicting case lost the first-seen entry for {:?}",
                    conflict.semantic
                )
            });
            assert_eq!(
                (conflict.first_priority, conflict.first_value_type),
                (kept.priority, kept.value_type),
                "H-REGISTRY shrink audit: the later declaration no longer loses to the first-seen contract for {:?}",
                conflict.semantic
            );
            assert_eq!(
                conflict_warnings, 1,
                "H-REGISTRY shrink audit: a conflicting case must keep exactly one incompatible warning, got {conflict_warnings}: {diagnostics:?}"
            );
            assert_eq!(
                tie_warnings, 0,
                "H-REGISTRY shrink audit: a conflicting case gained a tied-priority warning: {diagnostics:?}"
            );
        }
        RequestedShape::TiedSameModule | RequestedShape::TiedCrossModule => {
            assert!(
                is_compatible(&case.modules),
                "H-REGISTRY shrink audit: a tied case gained an incompatible repeated declaration"
            );
            assert_eq!(
                model.tie_messages.len(),
                1,
                "H-REGISTRY shrink audit: a tied case must keep exactly one tied-priority group, got {}: {:?}",
                model.tie_messages.len(),
                model.tie_messages
            );
            assert!(
                tied_priority(&model.entries).is_some(),
                "H-REGISTRY shrink audit: a tied case has no priority shared by two semantics"
            );
            if case.requested == RequestedShape::TiedSameModule {
                assert!(
                    has_same_module_tie(&model.entries),
                    "H-REGISTRY shrink audit: a same-module tie case no longer has two tied semantics in one module"
                );
            } else {
                assert!(
                    has_cross_module_tie(&model.entries),
                    "H-REGISTRY shrink audit: a cross-module tie case no longer has tied semantics from different modules"
                );
            }
            assert_eq!(
                conflict_warnings, 0,
                "H-REGISTRY shrink audit: a tied case gained an incompatible warning: {diagnostics:?}"
            );
            assert_eq!(
                tie_warnings, 1,
                "H-REGISTRY shrink audit: a tied case must keep exactly one tied-priority warning, got {tie_warnings}: {diagnostics:?}"
            );
        }
    }

    assert!(
        !aggregate.is_empty(),
        "H-REGISTRY shrink audit: a shrunk case produced an empty aggregate"
    );
}

/// Deterministic shrink audit for the composed case-construction strategy.
///
/// The shape and its fault descriptor come from chained `no_shrink` selections,
/// so `simplify()` can only shrink the module/declaration counts and the text
/// stem. This audit proves that on the actual case strategy: it repeatedly
/// calls `simplify()` and fails when the shape changes, when a conflicting
/// case's first-seen contract moves, when a tied case's shared priority moves,
/// or when a simplified case loses — or gains — its incompatible or
/// tied-priority warning.
///
/// [`sample_strategy`]'s other fields are derived from the case and cannot feed
/// back into it, so auditing the case strategy covers every path that can
/// change the shape. A shrinkable shape selector (the pre-fix `u8` bitset, or a
/// `select` without `no_shrink`) is caught here: the meta tree eventually
/// simplifies, the shape tag changes, and the assertion names both tags. This
/// audit fails on the `select` regression after a few dozen steps, well inside
/// the guard.
fn assert_shrink_preserves_faults(strategy: &BoxedStrategy<RegistryCase>) {
    let mut runner = TestRunner::new(Config {
        cases: 1,
        max_local_rejects: 0,
        rng_algorithm: RngAlgorithm::ChaCha,
        rng_seed: RngSeed::Fixed(0x5eed_c0de),
        failure_persistence: None,
        ..Config::default()
    });

    let mut audited = [false; 4];
    let mut simplifications = 0_usize;
    for _ in 0..SHRINK_AUDIT_MAX_TREES {
        if audited.iter().all(|reached| *reached) {
            break;
        }
        let mut tree = strategy
            .new_tree(&mut runner)
            .expect("H-REGISTRY composed strategy tree");
        let initial = tree.current();
        let witness = shape_witness(&initial);
        audited[shape_index(witness.shape)] = true;
        assert_case_fault_intact(&initial);

        let mut guard = 0_usize;
        while guard < SHRINK_AUDIT_MAX_STEPS && tree.simplify() {
            guard += 1;
            simplifications += 1;
            let case = tree.current();
            let next = shape_witness(&case);
            assert_eq!(
                next.shape,
                witness.shape,
                "H-REGISTRY shrink audit: shrinking changed the case shape from {} to {} after {guard} simplification step(s)",
                witness.shape.label(),
                next.shape.label()
            );
            assert_eq!(
                next.first_seen, witness.first_seen,
                "H-REGISTRY shrink audit: shrinking changed a conflicting case's first-seen winner"
            );
            assert_eq!(
                next.tie_priority, witness.tie_priority,
                "H-REGISTRY shrink audit: shrinking changed a tied case's shared priority"
            );
            assert_case_fault_intact(&case);
        }
    }

    assert!(
        audited.iter().all(|reached| *reached),
        "H-REGISTRY shrink audit: the fixed-seed audit sampled {SHRINK_AUDIT_MAX_TREES} trees without reaching every shape (compatible={}, conflicting={}, tied_same_module={}, tied_cross_module={}); a shape branch is unreachable or the selector is broken",
        audited[0],
        audited[1],
        audited[2],
        audited[3]
    );
    assert!(
        simplifications > 0,
        "H-REGISTRY shrink audit: the composed shrink audit simplified nothing, so it certifies nothing"
    );
}

/// Build the composed `H-REGISTRY` case strategy and run the shrink audit.
///
/// `run_property` and [`run_shrink_audit`] both go through here, so the AC-N3
/// control cannot certify a different audit body than the generative entrypoint:
/// [`case_strategy`] and [`assert_shrink_preserves_faults`] are assembled once.
fn audit_shrink_strategy(limits: RegistryLimits) -> Result<(), String> {
    let cases = case_strategy(limits)?;
    assert_shrink_preserves_faults(&cases);
    Ok(())
}

/// Run the same composed case-strategy shrink audit `run_property` runs, from a
/// bare bounds profile and without any property-registry context.
///
/// `Err` is the [`checked_registry_limits`] rejection for a bound outside
/// `2..=7` modules, `2..=16` declarations or `8..=64` text bytes, returned
/// before any strategy allocates. An audit failure is the same assertion panic
/// `run_property` raises, because that is the witness the AC-N3 control needs to
/// keep; this function never reads `PNP_PROPERTY_CONTEXT` and never constructs a
/// `PropertyRun`.
pub fn run_shrink_audit(
    max_modules: u64,
    max_declarations: u64,
    max_text_bytes: u64,
) -> Result<(), String> {
    let limits = checked_registry_limits(max_modules, max_declarations, max_text_bytes)?;
    audit_shrink_strategy(limits)
}

/// Run the registry-selected `H-REGISTRY` property.
pub fn run_property() {
    let run = PropertyRun::new(
        "H-REGISTRY",
        "proptest_scheduler_region_split_registry",
    )
    .expect(
        "H-REGISTRY registry context (cargo xtask test --summary --properties --property H-REGISTRY --tier routine)",
    );
    let limits = checked_registry_limits(
        run.bound("max_modules")
            .expect("max_modules registry bound"),
        run.bound("max_declarations")
            .expect("max_declarations registry bound"),
        run.bound("max_text_bytes")
            .expect("max_text_bytes registry bound"),
    )
    .expect("H-REGISTRY safety ceilings");
    assert_normative_catalog().expect("H-REGISTRY normative priority catalog");

    let strategy = sample_strategy(&limits).expect("H-REGISTRY declaration strategy");
    assert_substantive_population(&strategy).expect("H-REGISTRY substantive population");
    audit_shrink_strategy(limits).expect("H-REGISTRY case strategy and shrink audit");

    run.check(&strategy, |sample, _guard| {
        check_sample(&sample).map_err(TestCaseError::fail)
    })
    .expect("H-REGISTRY compatible aggregation, first-seen conflicts and tied-priority warnings");
}
